int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    // We'll store the matrix as a 2D vector of long long for safety.
    vector<vector<long long>> mat(N, vector<long long>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> mat[i][j];
        }
    }

    // We'll keep track of the current mapping from logical indices to physical indices.
    // Initially, logical row i corresponds to physical row i, similarly for columns.
    vector<int> row_map(N), col_map(N);
    iota(row_map.begin(), row_map.end(), 0);
    iota(col_map.begin(), col_map.end(), 0);

    // Flags to track if the matrix is transposed (rotated 90°) or reflected.
    // We'll represent the transformation as:
    //   - A flag 'transposed': if true, then logical (r, c) accesses physical (row_map[c], col_map[r]).
    //   - Otherwise, logical (r, c) accesses physical (row_map[r], col_map[c]).
    // Additionally, we track horizontal and vertical reflections applied *after* transpose.
    // But it's simpler: we can keep the matrix fixed and just adjust the mapping.
    // Actually, we'll handle all operations by updating row_map, col_map, and a transpose flag.

    bool transposed = false; // false means normal orientation, true means rows and columns swapped.

    auto get_physical = [&](int r, int c) -> pair<int,int> {
        if (transposed) {
            // logical (r,c) -> physical (row_map[c], col_map[r])
            return {row_map[c], col_map[r]};
        } else {
            return {row_map[r], col_map[c]};
        }
    };

    auto set_val = [&](int r, int c, long long v) {
        auto [pr, pc] = get_physical(r, c);
        mat[pr][pc] = v;
    };

    auto get_val = [&](int r, int c) -> long long {
        auto [pr, pc] = get_physical(r, c);
        return mat[pr][pc];
    };

    while (Q--) {
        string cmd;
        cin >> cmd;
        if (cmd == "WRITE") {
            int r, c;
            long long v;
            cin >> r >> c >> v;
            // Convert to 0-indexed
            r--; c--;
            set_val(r, c, v);
        } else if (cmd == "COPY") {
            int r1, c1, r2, c2;
            cin >> r1 >> c1 >> r2 >> c2;
            r1--; c1--; r2--; c2--;
            long long val = get_val(r1, c1);
            set_val(r2, c2, val);
        } else if (cmd == "SWAP_ROW") {
            int r1, r2;
            cin >> r1 >> r2;
            r1--; r2--;
            if (!transposed) {
                swap(row_map[r1], row_map[r2]);
            } else {
                // When transposed, rows correspond to columns in physical.
                // SWAP_ROW on logical rows means swapping the corresponding columns in physical.
                swap(col_map[r1], col_map[r2]);
            }
        } else if (cmd == "SWAP_COL") {
            int c1, c2;
            cin >> c1 >> c2;
            c1--; c2--;
            if (!transposed) {
                swap(col_map[c1], col_map[c2]);
            } else {
                swap(row_map[c1], row_map[c2]);
            }
        } else if (cmd == "ROTATE") {
            // 90-degree clockwise rotation.
            // This is equivalent to transpose then reverse rows (or reverse columns then transpose).
            // We'll combine with current transpose flag.
            // New effect: logical (r,c) -> after rotation, it goes to (c, N-1-r).
            // We can update our mapping to incorporate this.
            // One way: toggle transpose and then reverse the row mapping (if not transposed) or column mapping (if transposed).
            // Actually, let's derive carefully.
            // Suppose we have current transformation T that maps logical to physical.
            // After rotation R, the new transformation is T ∘ R^{-1} (since we want to access the rotated matrix).
            // R: (r,c) -> (c, N-1-r). So R^{-1}: (r,c) -> (N-1-c, r).
            // So we need to compose T with this inverse rotation.
            // We can do this by updating row_map, col_map, and transposed flag.
            // Instead of complex composition, we can simulate by building new maps.
            // But we can also do it simply:
            // If we are not transposed, rotation = transpose then reverse rows.
            // If we are transposed, rotation = reverse columns then transpose? Let's test.
            // Actually, simpler: we can just apply the rotation to the mapping arrays directly.
            // We'll create temporary new row_map and col_map.
            // The transformation T maps logical (r,c) to physical (pr, pc).
            // After rotation, we want to access the rotated matrix, so we need a new transformation T' such that
            // T'(r,c) = T(original position of (r,c) in rotated matrix) = T(c, N-1-r).
            // So:
            //   if transposed: T(r,c) = (row_map[c], col_map[r])
            //   else: T(r,c) = (row_map[r], col_map[c])
            // So T'(r,c) = T(c, N-1-r).
            // Let's compute based on transposed flag.
            vector<int> new_row_map(N), new_col_map(N);
            if (!transposed) {
                // T(c, N-1-r) = (row_map[c], col_map[N-1-r])
                // So new row_map[r] = row_map[c]? No, we need mapping for each r,c.
                // Actually T'(r,c) = (row_map[c], col_map[N-1-r]).
                // So for new transformation, we want to represent it as either:
                //   new_transposed = true: T'(r,c) = (new_row_map[c], new_col_map[r])
                //   or new_transposed = false: T'(r,c) = (new_row_map[r], new_col_map[c])
                // We can choose to keep transposed flag false and set:
                //   new_row_map[r] = row_map[c]? That doesn't work because row_map depends on c.
                // Better: we can set transposed = true and then define:
                //   new_row_map[c] = row_map[c]? Let's derive.
                // If we set new_transposed = true, then we want:
                //   T'(r,c) = (new_row_map[c], new_col_map[r]) = (row_map[c], col_map[N-1-r]).
                // So we can set:
                //   new_row_map[x] = row_map[x]  (for all x)
                //   new_col_map[x] = col_map[N-1-x] (for all x)
                // So we just toggle transpose and reverse col_map.
                transposed = true;
                reverse(col_map.begin(), col_map.end());
                // row_map stays the same.
            } else {
                // transposed = true: T(r,c) = (row_map[c], col_map[r])
                // T'(r,c) = T(c, N-1-r) = (row_map[N-1-r], col_map[c])
                // We want to keep transposed = true? Or set false?
                // If we keep transposed = true, we need:
                //   T'(r,c) = (new_row_map[c], new_col_map[r]) = (row_map[N-1-r], col_map[c])
                // So new_row_map[x] = row_map[N-1-x], new_col_map[x] = col_map[x]
                // That works: keep transposed true, reverse row_map.
                reverse(row_map.begin(), row_map.end());
                // col_map stays the same.
            }
        } else if (cmd == "REFLECT_HORIZONTALLY") {
            // Reflect horizontally: flip left-right. (r,c) -> (r, N-1-c)
            // This affects the column mapping.
            if (!transposed) {
                // T(r,c) = (row_map[r], col_map[c])
                // After reflection H: T_H(r,c) = T(r, N-1-c) = (row_map[r], col_map[N-1-c])
                // So we keep transposed false, reverse col_map.
                reverse(col_map.begin(), col_map.end());
            } else {
                // T(r,c) = (row_map[c], col_map[r])
                // T_H(r,c) = T(r, N-1-c) = (row_map[N-1-c], col_map[r])
                // Keep transposed true, reverse row_map.
                reverse(row_map.begin(), row_map.end());
            }
        } else if (cmd == "REFLECT_VERTICALLY") {
            // Reflect vertically: flip top-bottom. (r,c) -> (N-1-r, c)
            if (!transposed) {
                // T(r,c) = (row_map[r], col_map[c])
                // T_V(r,c) = T(N-1-r, c) = (row_map[N-1-r], col_map[c])
                // Keep transposed false, reverse row_map.
                reverse(row_map.begin(), row_map.end());
            } else {
                // T(r,c) = (row_map[c], col_map[r])
                // T_V(r,c) = T(N-1-r, c) = (row_map[c], col_map[N-1-r])
                // Keep transposed true, reverse col_map.
                reverse(col_map.begin(), col_map.end());
            }
        }
    }

    // After all commands, compute hash.
    // Read the coefficients.
    vector<long long> a(N), b(N);
    for (int i = 0; i < N; i++) cin >> a[i];
    for (int i = 0; i < N; i++) cin >> b[i];

    long long hash_val = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            long long val = get_val(i, j);
            hash_val = (hash_val + a[i] * b[j] * val);
        }
    }
    cout << hash_val << "\n";

    return 0;
}

