// transform: (r,c) -> (ar*r + ac*c + br, ar2*r + ac2*c + bc) where values use N-1 offset
// represent symmetry as index 0..7
int sym; // 0=identity, 1=rot90, 2=rot180, 3=rot270, 4=flipH, 5=flipV, 6=diagMain, 7=diagAnti

pair<int,int> applyTrans(int r, int c) {
    int M = N - 1;
    switch(sym) {
        case 0: return {r, c};
        case 1: return {c, M-r};
        case 2: return {M-r, M-c};
        case 3: return {M-c, r};
        case 4: return {r, M-c};
        case 5: return {M-r, c};
        case 6: return {c, r};
        case 7: return {M-c, M-r};
    }
    return {r,c};
}

pair<int,int> getPhys(int r, int c) {
    return applyTrans(rp[r], cp[c]);
}

int& cell(int r, int c) {
    auto [pr, pc] = getPhys(r, c);
    return mat[pr][pc];
}

