#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    // Base matrix values.
    vector<vector<int64>> a(N, vector<int64>(N, 0));

    // Current view:
    // logical cell (i, j) corresponds to base cell:
    // row = rowMap[ maybe reversed i ]
    // col = colMap[ maybe reversed j ]
    vector<int> rowMap(N), colMap(N);
    iota(rowMap.begin(), rowMap.end(), 0);
    iota(colMap.begin(), colMap.end(), 0);

    bool transposed = false; // whether logical axes are swapped
    bool revRow = false;     // reverse logical row axis
    bool revCol = false;     // reverse logical col axis

    auto basePos = [&](int x, int y) -> pair<int,int> {
        // x, y are 0-based logical coordinates
        int i = x, j = y;
        if (transposed) swap(i, j);
        if (revRow) i = N - 1 - i;
        if (revCol) j = N - 1 - j;
        return {rowMap[i], colMap[j]};
    };

    for (int k = 0; k < M; ++k) {
        int t;
        cin >> t;

        if (t == 1) {
            int x, y;
            int64 v;
            cin >> x >> y >> v;
            --x; --y;
            auto [r, c] = basePos(x, y);
            a[r][c] = v;
        } else if (t == 2) {
            int x1, y1, x2, y2;
            cin >> x1 >> y1 >> x2 >> y2;
            --x1; --y1; --x2; --y2;
            auto [r1, c1] = basePos(x1, y1);
            auto [r2, c2] = basePos(x2, y2);
            a[r2][c2] = a[r1][c1];
        } else if (t == 3) {
            int x1, x2;
            cin >> x1 >> x2;
            --x1; --x2;
            if (!transposed) {
                if (revRow) {
                    x1 = N - 1 - x1;
                    x2 = N - 1 - x2;
                }
                swap(rowMap[x1], rowMap[x2]);
            } else {
                if (revCol) {
                    x1 = N - 1 - x1;
                    x2 = N - 1 - x2;
                }
                swap(colMap[x1], colMap[x2]);
            }
        } else if (t == 4) {
            int y1, y2;
            cin >> y1 >> y2;
            --y1; --y2;
            if (!transposed) {
                if (revCol) {
                    y1 = N - 1 - y1;
                    y2 = N - 1 - y2;
                }
                swap(colMap[y1], colMap[y2]);
            } else {
                if (revRow) {
                    y1 = N - 1 - y1;
                    y2 = N - 1 - y2;
                }
                swap(rowMap[y1], rowMap[y2]);
            }
        } else if (t == 5) {
            // Rotate 90 degrees clockwise:
            // new(i,j) = old(N-1-j, i)
            // Transform view parameters accordingly.
            transposed = !transposed;
            swap(revRow, revCol);
            revRow = !revRow;
        } else if (t == 6) {
            // Horizontal reflection (flip top-bottom):
            revRow = !revRow;
        } else if (t == 7) {
            // Vertical reflection (flip left-right):
            revCol = !revCol;
        }
    }

    int Q;
    cin >> Q;
    int64 ans = 0;
    for (int i = 0; i < Q; ++i) {
        int x, y;
        int64 k;
        cin >> x >> y >> k;
        --x; --y;
        auto [r, c] = basePos(x, y);
        ans += a[r][c] * k;
    }

    cout << ans << '\n';
    return 0;
}
